echo "=== VERSION ==="; uname -r; cut -c1-100 /proc/version; echo "=== GATE ==="; echo -n "enabled="; cat /sys/kernel/thermal_perf/enabled 2>&1; echo -n "stats="; cat /sys/kernel/thermal_perf/stats 2>&1; echo "=== HOTTEST ZONES ==="; for z in /sys/class/thermal/thermal_zone*; do echo "$(cat $z/type 2>/dev/null) $(cat $z/temp 2>/dev/null)"; done | sort -k2 -n | tail -6; echo "=== COOLING DEVICES NON-ZERO ==="; for c in /sys/class/thermal/cooling_device*; do [ -d "$c" ] || continue; s=$(cat $c/cur_state 2>/dev/null); [ -n "$s" ] && [ "$s" != "0" ] && echo "$(cat $c/type 2>/dev/null) = $s"; done; echo "(اگر بالا خالی است = همه صفر)"; echo "=== CPU ==="; for c in 0 6; do echo "cpu$c cur=$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_cur_freq 2>/dev/null) min=$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_min_freq 2>/dev/null) max=$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_max_freq 2>/dev/null) hwmax=$(cat /sys/devices/system/cpu/cpu$c/cpufreq/cpuinfo_max_freq 2>/dev/null) gov=$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_governor 2>/dev/null)"; done; echo "=== ATM (/proc/clatm) ==="; head -30 /proc/clatm 2>&1; echo "=== GPU (/proc/gpufreqv2/limit_table) ==="; head -30 /proc/gpufreqv2/limit_table 2>&1; echo "=== SSPM ==="; head -12 /proc/sspm_thermal_throttle 2>&1; echo "=== DONE ==="
